import { post } from '../utils/request';

/**
 * UC-AUTH-01 Đăng nhập hệ thống
 * @param {string} email
 * @param {string} password
 * @returns {Promise<object>} response envelope (success, data, meta)
 */
export const login = async (email, password) => {
    return await post('/auth/login', { email, password }, { isPublic: true });
};

/**
 * Yêu cầu đặt lại mật khẩu (Forgot Password)
 * @param {string} email
 * @returns {Promise<object>} response envelope
 */
export const forgotPassword = async (email) => {
    return await post('/auth/forgot-password', { email }, { isPublic: true });
};

/**
 * Đặt lại mật khẩu mới (Reset Password)
 * @param {string} token
 * @param {string} newPassword
 * @returns {Promise<object>} response envelope
 */
export const resetPassword = async (token, newPassword) => {
    return await post('/auth/reset-password', { token, newPassword }, { isPublic: true });
};
